#include "Halide.h"

// include common definitions (DATA_TYPE, M, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays using Halide, mimicking the original C init_array().
 *
 * C: m x n, indexed as C[i][j] in C code.
 * B: m x n, indexed as B[i][j] in C code.
 * A: m x m, symmetric, lower triangle stored, indexed as A[i][j] (j <= i) in C code.
 *
 * In Halide Buffers we use:
 *   - First dimension = column index (j)
 *   - Second dimension = row index (i)
 * so:
 *   C_buf(j, i) corresponds to C[i][j]
 *   B_buf(j, i) corresponds to B[i][j]
 *   A_buf(j, i) corresponds to A[i][j]
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Initialize C and B:
    //   C[i][j] = ( (i + j) % 100 ) / m;
    //   B[i][j] = ( (n + i - j) % 100 ) / m;
    Func init_C("init_C"), init_B("init_B");

    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // Initialize A:
    //   for i = 0..m-1:
    //     for j = 0..i:   A[i][j] = ((i + j) % 100) / m;
    //     for j = i+1..m-1: A[i][j] = -999;
    Func init_A("init_A");
    Expr lower_val = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    Expr upper_val = cast<num_t>(-999);
    // Condition j <= i is (j <= i) -> (x <= y) in (j,i) coordinates.
    init_A(j, i) = select(j <= i, lower_val, upper_val);

    // Realize into the provided buffers.
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: M x N  -> Buffer(n, m) [x=j, y=i]
    //   B: M x N  -> Buffer(n, m) [x=j, y=i]
    //   A: M x M  -> Buffer(m, m) [x=j, y=i]
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // ImageParams for the inputs (C, A, B)
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Bind ImageParams to the initialized Buffers
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Halide Vars and RDom
    Var x("x"), y("y");     // x = column index j, y = row index i
    RDom k(0, m, "k");      // reduction over index k (0 .. m-1)

    // Define the SYMM kernel in Halide.
    //
    // Original C kernel (conceptually):
    //   C := alpha * A * B + beta * C, with A symmetric (MxM), B (MxN), C (MxN).
    //
    // We express it directly as:
    //   C_out(r, j) = beta * C0(r, j) + alpha * sum_{i=0..M-1} B(i, j) * A_sym(r, i)
    // where:
    //   A_sym(r, i) = A[r][i] if i <= r
    //               = A[i][r] if i > r
    //
    // In terms of Buffers:
    //   A[r][i] -> A_param(i, r)
    //   A[i][r] -> A_param(r, i)
    //   B[i][j] -> B_param(j, i)
    //   C[r][j] -> C_param(j, r)
    Func symm("symm");

    // Pure definition: beta * C
    symm(x, y) = Expr(beta) * C_param(x, y);

    // Reduction definition: add alpha * sum_k B(k,j) * A_sym(r,k)
    Expr a_sym = select(k <= y,
                        A_param(k, y),   // A[y][k]
                        A_param(y, k));  // A[k][y], using symmetry
    symm(x, y) += Expr(alpha) * B_param(x, k) * a_sym;

    // Schedule:
    // Pure stage: default (y outer, x inner)
    // Update stage: explicitly set loop order to y (outer), x (middle), k (inner)
    symm.update().reorder(k, x, y);

    // Compile the kernel to machine code
    symm.compile_jit();

    // Measure execution time
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write results back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the gemm.cpp example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                std::cerr << C(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
