    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Note: i is the C-row index [0..m), j is the C-column index [0..n)
    // but Buffer is indexed as (j, i).

    Func init_C("init_C"), init_B("init_B"), init_A("init_A");

    // C[i][j] = ((i + j) % 100) / m;
