    //   for (j = 0; j <= i; j++)
    //     A[i][j] = ((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //     A[i][j] = -999;
    // }
    //
    // A[i][j] -> A(j, i) in the Buffer.
    init_A(j, i) = select(j <= i,
                          cast<num_t>(((i + j) % 100)) / cast<int>(m),
                          cast<num_t>(-999));

    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int m = M;
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    // C, B are MxN in C, so shape is (N, M) in Halide.
    // A is MxM in C, so shape is (M, M) in Halide.
