    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Vars and RDom.
    Var i("i"), j("j");
    // A is MxM, and we loop over k in [0, M).
    RDom k(0, A.dim(0).extent(), "k");

    // Main kernel: symmetric matrix-matrix multiplication
    //
    // Original C kernel computes:
    //
    //   C := alpha * A * B + beta * C
    //
    // with A symmetric (lower part stored) and
    // B, C of size MxN.
    //
    // It can be written mathematically as:
    //
    //   C[i][j] = beta * C[i][j]
    //             + alpha * sum_{k=0..M-1} A_sym[i][k] * B[k][j],
