    {
        // A[i][k] -> A_param(k, i)
        // A[k][i] -> A_param(i, k)
        Expr a_sym = select(k <= i,
                            A_param(k, i),
                            A_param(i, k));

        // B[k][j] -> B_param(j, k)
        symm(j, i) += Expr(alpha) * a_sym * B_param(j, k);
    }

    // Simple schedule mirroring the traversal order of the C code:
    // j is the fast (x) dimension, i is the slow (y) dimension.
    symm.reorder(j, i);
    symm.update().reorder(j, k, i);

    // JIT-compile the kernel.
    symm.compile_jit();

    // Measure execution time of a single run.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C (safe because C is only read
    // at the same (i,j) where it's written, and not across pixels).
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

