 *
 * C[i][j] = ( (i + j) % 100 ) / m
 * B[i][j] = ( (n + i - j) % 100 ) / m
 *
 * A is symmetric (only lower triangle is used):
 *   for j <= i: A[i][j] = ( (i + j) % 100 ) / m
 *   for j >  i: A[i][j] = -999  (unused region)
 *
 * Buffers are laid out as:
 *   C(j, i) corresponds to C[i][j]
 *   B(j, i) corresponds to B[i][j]
 *   A(j, i) corresponds to A[i][j]
 */
static
void init_array(int m, int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // C and B are M x N (C(i,j), B(i,j)) -> Buffer(j, i)
    Func init_C("init_C"), init_B("init_B");

    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // A is M x M, with lower triangle initialized and upper triangle set to -999
    Func init_A("init_A");
    Expr valA = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    Expr unused = cast<num_t>(-999);
    init_A(j, i) = select(j <= i, valA, unused);

    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C, B are MxN -> Buffer(n, m)
    //   A is MxM     -> Buffer(m, m)
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // ImageParams to expose A, B, C to the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Scalar Params for alpha and beta
    Param<num_t> alpha_param("alpha");
    Param<num_t> beta_param("beta");
    alpha_param.set(alpha);
    beta_param.set(beta);

    // Vars: x corresponds to column j, y to row i
    Var x("x"), y("y");

    // We will construct the final value of C(i,j) in closed form.
    //
    // Original kernel (in C):
    //   for (i = 0; i < M; i++)
    //     for (j = 0; j < N; j++) {
    //       temp2 = 0;
    //       for (k = 0; k < i; k++) {
    //         C[k][j] += alpha * B[i][j] * A[i][k];
    //         temp2 += B[k][j] * A[i][k];
    //       }
    //       C[i][j] = beta * C[i][j] + alpha * B[i][j] * A[i][i] + alpha * temp2;
    //     }
    //
    // After algebraic simplification, the final value of C[r][j] is:
    //
    //   C(r, j) = beta * C0(r, j)
    //             + alpha * B[r][j] * A[r][r]
    //             + alpha * sum_{k=0..r-1} B[k][j] * A[r][k]
    //             + alpha * sum_{i=r+1..M-1} B[i][j] * A[i][r]
    //
    // where C0 is the initial C.
    //
    // We implement the two sums as reductions in Halide.

    // S1(x, y) = sum_{k < y} B[k][x] * A[y][k]
    // Mapping to buffers:
    //   B[k][j] -> B_param(j, k)  => B_param(x, r1)
    //   A[r][k] -> A_param(k, r)  => A_param(r1, y)
    Func S1("S1");
    Func S2("S2");

    RDom r1(0, m, "r1");
    RDom r2(0, m, "r2");

    S1(x, y) = cast<num_t>(0);
    // Only k < y contribute; others contribute 0
    S1(x, y) += select(r1 < y,
                       B_param(x, r1) * A_param(r1, y),
                       cast<num_t>(0));

    // S2(x, y) = sum_{i > y} B[i][x] * A[i][y]
    // Mapping:
    //   B[i][j] -> B_param(j, i)  => B_param(x, r2)
    //   A[i][y] -> A_param(y, i)  => A_param(y, r2)
    S2(x, y) = cast<num_t>(0);
    S2(x, y) += select(r2 > y,
                       B_param(x, r2) * A_param(y, r2),
                       cast<num_t>(0));

    // Final result Func: symm(x, y) corresponds to C[y][x]
    Func symm("symm");

    symm(x, y) =
        beta_param * C_param(x, y) +
        alpha_param * (B_param(x, y) * A_param(y, y) +
                       S1(x, y) + S2(x, y));

    // Optional: make loop order explicit to mirror C loops (i outer, j inner).
    // Here, y corresponds to i and x corresponds to j.
    // By default Halide uses y outer, x inner, so this is already the case.

    // Bind the ImageParams and Params (already done above) and JIT-compile.
    symm.compile_jit();

    // Time the kernel execution (including only the Halide realization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: write results back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to avoid dead-code elimination)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                std::cerr << C(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds with microsecond precision
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
