using namespace Halide;

/**
 * Initialize arrays C, A, B as in the original C version, but using Halide
 * Buffers instead of raw C arrays.
 *
 * Original C shapes:
 *   C[m][n], A[m][m], B[m][n]
 *
 * Buffer shapes (Halide: first dim = fastest-varying = column):
 *   C: (n, m)  -> C(j, i) corresponds to C[i][j]
 *   B: (n, m)  -> B(j, i) corresponds to B[i][j]
 *   A: (m, m)  -> A(j, i) corresponds to A[i][j]
 */
static
void init_array(int m, int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {

    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // C[i][j] = ((i + j) % 100) / m;
    Func init_C("init_C");
    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);

    // B[i][j] = ((n + i - j) % 100) / m;
    Func init_B("init_B");
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // A is lower-triangular; upper part is filled with -999 sentinel
    // for (i = 0; i < m; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = ((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //     A[i][j] = -999;
    // }
    Func init_A("init_A");
    init_A(j, i) = select(j <= i,
                          cast<num_t>(((i + j) % 100)) / cast<int>(m),
                          cast<num_t>(-999));

    // Realize into the provided Buffers.
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (Polybench-style)
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers with column-major logical layout (x = column, y = row)
    // C: m x n  -> (n, m)
    // B: m x n  -> (n, m)
    // A: m x m  -> (m, m)
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Wrap Buffers as ImageParams for the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Vars and reduction domain
    Var i("i"), j("j");
    RDom k(0, A_param.dim(0).extent(), "k"); // k ranges over 0..m-1

    // SYMM kernel:
    //
    // BLAS semantics:
    //   SIDE = 'L', UPLO = 'L'
    //   C := alpha * A * B + beta * C
    //
    // A is symmetric; only the lower triangle is stored. The original C kernel
    // uses a more complex triangular algorithm, but the final result is exactly
    // the symmetric matrix-multiply:
    //
    //   C_new(i,j) = beta*C_old(i,j) + alpha * sum_k A_sym(i,k) * B(k,j)
    //
    // where
    //   A_sym(i,k) = A[i][k]    if k <= i
    //              = A[k][i]    if k > i
    //
    // We reconstruct A_sym on the fly from the stored lower triangle.
    Func symm("symm");

    // Map indices:
    //   original C[i][j] -> C_param(j, i)
    //   original B[k][j] -> B_param(j, k)
    //   original A[i][k] -> A_param(k, i)
    //
    // A_sym(i,k) reconstructed from A_param:
    Expr A_sym_ik = select(i >= k,
                           A_param(k, i),  // A[i][k]
                           A_param(i, k)); // A[k][i] (symmetric part)

    // Pure definition: scaled original C
    symm(j, i) = Expr(beta) * C_param(j, i);

    // Reduction: accumulate alpha * A_sym(i,k) * B(k,j)
    symm(j, i) += Expr(alpha) * A_sym_ik * B_param(j, k);

    // Simple schedule roughly reflecting the original loop structure:
    // Outer over rows (i), inner over columns (j), innermost over k.
    symm.reorder(j, i);                // x (j) varies fastest in pure definition
    symm.update().reorder(k, j, i);    // innermost k, then j, then i

    // JIT-compile the kernel
    symm.compile_jit();

    // Time the kernel execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel; result overwrites C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix (similar to Polybench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
